export const CONTROL_VIEWS=['Home','Conversations','Research','Projects','Notifications','Converters','Chat','Search','Documents','Tasks','Notes','Memory','Code','Media','Games','Controls','Connections','Permissions','Appearance','Activity','Settings'];
export function voiceCommand(text){const q=String(text).toLowerCase().trim().replace(/[.!?]+$/,'');if(/^(stop listening|stop microphone|mic band|रुको|बंद करो)$/.test(q))return{type:'stop'};if(/^(scroll down|नीचे|neeche)$/.test(q))return{type:'scroll',delta:380};if(/^(scroll up|ऊपर|upar)$/.test(q))return{type:'scroll',delta:-380};for(const name of CONTROL_VIEWS){if(q===name.toLowerCase()||q==='open '+name.toLowerCase()||q==='go to '+name.toLowerCase())return{type:'navigate',view:name}}if(/^(new chat|new conversation)$/.test(q))return{type:'new-chat'};if(/^(read answer|read last answer)$/.test(q))return{type:'read'};const ask=text.match(/^(?:ask apex|question|पूछो|apex se pucho)\s+([\s\S]+)$/i);if(ask)return{type:'draft',text:ask[1].slice(0,2000)};return{type:'unknown',text:String(text).slice(0,2000)}}
export function handPose(points){if(!Array.isArray(points)||points.length!==21||points.some(p=>!Number.isFinite(p.x)||!Number.isFinite(p.y)))return{kind:'none'};const dist=(a,b)=>Math.hypot(points[a].x-points[b].x,points[a].y-points[b].y),span=dist(0,9);if(span<.025)return{kind:'none'};const pinch=dist(4,8)/span<.28;const fingers=[8,12,16,20].map((tip,i)=>dist(0,tip)>dist(0,[6,10,14,18][i])*1.15);return{kind:pinch?'pinch':fingers.every(Boolean)?'palm':fingers[0]&&!fingers[1]&&!fingers[2]&&!fingers[3]?'point':'neutral',x:Math.max(0,Math.min(1,1-points[8].x)),y:Math.max(0,Math.min(1,points[8].y))}}
export function safeGestureTarget(element){const target=element?.closest?.('button,a,input[type=checkbox],summary');if(!target||target.disabled||target.closest('[data-gesture-blocked],.access-shell,.modal-overlay,.memory-transfer,.free-image,.free-video,.code-studio'))return null;const label=(target.getAttribute('aria-label')||target.textContent||'').toLowerCase();if(/delete|forget|reset|sign|connect|export|download|generate|apply|import|send|purchase|clear|unlock|owner|enable|start camera|start microphone/.test(label))return null;return target}
export function scrollWorkspace(delta){const el=['.chat-scroll','.conversation-library','.page','.workspace'].map(s=>document.querySelector(s)).find(e=>e?.scrollHeight>e?.clientHeight);(el||document.scrollingElement)?.scrollBy({top:delta,behavior:document.documentElement.dataset.readingMotion==='reduce'||window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})}
